-- Release N: EXPAND — additive only, safe for the old app version
ALTER TABLE dbo.Orders
    ADD CustomerEmail nvarchar(320) NULL;
GO

-- Backfill in batches so we never lock the whole table
WHILE 1 = 1
BEGIN
    UPDATE TOP (5000) dbo.Orders
    SET CustomerEmail = c.Email
    FROM dbo.Orders o
    JOIN dbo.Customers c ON c.Id = o.CustomerId
    WHERE o.CustomerEmail IS NULL;

    IF @@ROWCOUNT = 0 BREAK;
    WAITFOR DELAY '00:00:00.100';
END
GO

-- Release N+1 (after the new version is fully rolled out): CONTRACT
